#include <iostream>
#include <vector>

int main()
{
    std::vector<int> values{};
    int x{};

    while (std::cin >> x)
    {
        values.push_back(x);
    }

    std::cout << "size " << values.size() << "\n";

    if (values.empty())
    {
        std::cout << "first none\n";
        std::cout << "last none\n";
        std::cout << "middle none\n";
    }
    else
    {
        std::cout << "first " << values.front() << "\n";
        std::cout << "last " << values.back() << "\n";
        std::cout << "middle " << values[values.size() / 2] << "\n";
    }

    return 0;
}
